function* queue() {
  yield "Ada";
  yield "Bo";
  yield "Cy";
}

const line = queue();
console.log(line.find((name) => name === "Bo"));
console.log(line.next().done);

const names = ["Ada", "Bo", "Cy"].values();
console.log(names.find((name) => name === "Bo"));
console.log(names.next().value);
